import apiClient from './client'
import type { Page } from './page'

export type OptimizationType =
  | 'alert_threshold'
  | 'heal_rule'
  | 'check_frequency'
  | 'retention_policy'

export type OptimizationStatus = 'pending' | 'applied' | 'rejected' | 'rolled_back'

export interface SnapshotSummary {
  available: boolean
  kind?: string | null
  has_metric_baseline?: boolean
  keys?: string[]
}

export interface OptimizationListItem {
  id: number
  type: OptimizationType
  target_id: string
  current_value: string
  suggested_value: string
  reason: string
  expected_effect: string | null
  confidence: number
  status: OptimizationStatus
  applied_by: number | null
  applied_at: string | null
  rolled_back_at: string | null
  created_at: string
  updated_at: string
}

export interface OptimizationDetail extends OptimizationListItem {
  snapshot_summary: SnapshotSummary
  snapshot: Record<string, unknown>
}

export interface OptimizationEffect {
  id: number
  suggestion_id: number
  metric_name: string
  before_value: number
  after_value: number
  measured_at: string
}

export interface AnalyzeResult {
  total_drafts: number
  created: number
  created_ids: number[]
}

export interface ListParams {
  type?: OptimizationType
  status?: OptimizationStatus
  confidence_min?: number
  page?: number
  page_size?: number
}

export async function listOptimizations(
  params: ListParams = {}
): Promise<Page<OptimizationListItem>> {
  const response = await apiClient.get<Page<OptimizationListItem>>(
    '/v1/optimizations',
    { params }
  )
  return response.data
}

export async function getOptimization(id: number): Promise<OptimizationDetail> {
  const response = await apiClient.get<OptimizationDetail>(`/v1/optimizations/${id}`)
  return response.data
}

export async function applyOptimization(id: number): Promise<OptimizationDetail> {
  const response = await apiClient.post<OptimizationDetail>(
    `/v1/optimizations/${id}/apply`
  )
  return response.data
}

export async function rejectOptimization(id: number): Promise<OptimizationDetail> {
  const response = await apiClient.post<OptimizationDetail>(
    `/v1/optimizations/${id}/reject`
  )
  return response.data
}

export async function rollbackOptimization(id: number): Promise<OptimizationDetail> {
  const response = await apiClient.post<OptimizationDetail>(
    `/v1/optimizations/${id}/rollback`
  )
  return response.data
}

export async function analyzeNow(): Promise<AnalyzeResult> {
  const response = await apiClient.post<AnalyzeResult>('/v1/optimizations/analyze')
  return response.data
}

export async function listEffects(id: number): Promise<OptimizationEffect[]> {
  const response = await apiClient.get<OptimizationEffect[]>(
    `/v1/optimizations/${id}/effects`
  )
  return response.data
}
