<template>
  <div class="page-ai-optimizer">
    <h2 class="page-title">{{ t('ai.optimizer.title') }}</h2>

    <el-alert
      v-if="!settingsLoading && !aiEnabled"
      type="warning"
      :closable="false"
      show-icon
      class="gate-alert"
      :title="t('ai.optimizer.gateTitle')"
      :description="t('ai.optimizer.gateDesc')"
    />

    <el-card class="analyze-card">
      <template #header>
        <span>{{ t('ai.optimizer.analyzeCard') }}</span>
      </template>
      <el-button
        type="primary"
        :loading="analyzing"
        :disabled="!aiEnabled"
        @click="onAnalyze"
      >
        {{ t('ai.optimizer.analyzeButton') }}
      </el-button>
      <span class="form-hint">
        {{ t('ai.optimizer.analyzeHint') }}
      </span>
    </el-card>

    <el-card class="list-card">
      <template #header>
        <div class="list-header">
          <span>{{ t('ai.optimizer.listTitle') }}</span>
          <div class="filters">
            <el-select
              v-model="filterType"
              :placeholder="t('common.type')"
              clearable
              style="width: 150px"
              @change="onFilterChange"
            >
              <el-option :label="t('ai.optimizer.typeAlertThreshold')" value="alert_threshold" />
              <el-option :label="t('ai.optimizer.typeHealRule')" value="heal_rule" />
              <el-option :label="t('ai.optimizer.typeCheckFrequency')" value="check_frequency" />
              <el-option :label="t('ai.optimizer.typeRetentionPolicy')" value="retention_policy" />
            </el-select>
            <el-select
              v-model="filterStatus"
              :placeholder="t('common.status')"
              clearable
              style="width: 130px"
              @change="onFilterChange"
            >
              <el-option :label="t('ai.statusPending')" value="pending" />
              <el-option :label="t('ai.statusApplied')" value="applied" />
              <el-option :label="t('common.rejected')" value="rejected" />
              <el-option :label="t('ai.statusRolledBack')" value="rolled_back" />
            </el-select>
            <el-input-number
              v-model="filterConfidence"
              :min="0"
              :max="1"
              :step="0.1"
              :precision="1"
              :placeholder="t('ai.optimizer.minConfidence')"
              controls-position="right"
              style="width: 140px"
              @change="onFilterChange"
            />
            <el-button @click="loadList">{{ t('common.refresh') }}</el-button>
          </div>
        </div>
      </template>

      <el-table v-loading="loading" :data="items" stripe>
        <el-table-column prop="id" label="ID" width="70" />
        <el-table-column :label="t('common.type')" width="120">
          <template #default="{ row }">{{ typeText(row.type) }}</template>
        </el-table-column>
        <el-table-column prop="target_id" :label="t('common.target')" min-width="170" show-overflow-tooltip />
        <el-table-column :label="t('ai.optimizer.reasonSummary')" min-width="220" show-overflow-tooltip>
          <template #default="{ row }">{{ optimizerText(row.reason) }}</template>
        </el-table-column>
        <el-table-column :label="t('common.confidence')" width="90">
          <template #default="{ row }">{{ (row.confidence * 100).toFixed(0) }}%</template>
        </el-table-column>
        <el-table-column :label="t('common.status')" width="110">
          <template #default="{ row }">
            <el-tag :type="statusTagType(row.status)" size="small">
              {{ statusText(row.status) }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="created_at" :label="t('common.createdAt')" min-width="170" />
        <el-table-column :label="t('common.actions')" width="120" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="openDetail(row.id)">
              {{ t('ai.optimizer.detailAction') }}
            </el-button>
          </template>
        </el-table-column>
      </el-table>

      <div class="pagination">
        <el-pagination
          v-model:current-page="page"
          v-model:page-size="pageSize"
          :total="total"
          :page-sizes="[10, 20, 50]"
          layout="total, sizes, prev, pager, next"
          @current-change="loadList"
          @size-change="onSizeChange"
        />
      </div>
    </el-card>

    <!-- 详情抽屉 -->
    <el-drawer
      v-model="drawerVisible"
      :title="detail ? t('ai.optimizer.detailTitle', { id: detail.id }) : t('ai.optimizer.detailTitleEmpty')"
      size="60%"
      :destroy-on-close="true"
    >
      <div v-loading="detailLoading">
        <template v-if="detail">
          <el-descriptions :column="2" border>
            <el-descriptions-item :label="t('common.type')">{{ typeText(detail.type) }}</el-descriptions-item>
            <el-descriptions-item :label="t('common.status')">
              <el-tag :type="statusTagType(detail.status)" size="small">
                {{ statusText(detail.status) }}
              </el-tag>
            </el-descriptions-item>
            <el-descriptions-item :label="t('common.target')" :span="2">{{ detail.target_id }}</el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.currentValue')" :span="2">{{ optimizerText(detail.current_value) }}</el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.suggestedValue')" :span="2">
              <b>{{ optimizerText(detail.suggested_value) }}</b>
            </el-descriptions-item>
            <el-descriptions-item :label="t('common.confidence')">
              {{ (detail.confidence * 100).toFixed(0) }}%
            </el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.expectedEffect')">
              {{ detail.expected_effect ? optimizerText(detail.expected_effect) : '-' }}
            </el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.reason')" :span="2">{{ optimizerText(detail.reason) }}</el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.appliedBy')">{{ detail.applied_by ?? '-' }}</el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.appliedAt')">{{ detail.applied_at ?? '-' }}</el-descriptions-item>
            <el-descriptions-item :label="t('ai.optimizer.rolledBackAt')" :span="2">
              {{ detail.rolled_back_at ?? '-' }}
            </el-descriptions-item>
          </el-descriptions>

          <h4 class="section-title">{{ t('ai.optimizer.snapshotTitle') }}</h4>
          <el-alert
            v-if="!detail.snapshot_summary?.available"
            type="info"
            :closable="false"
            :title="t('ai.optimizer.snapshotUnavailable')"
          />
          <template v-else>
            <el-descriptions :column="2" border size="small">
              <el-descriptions-item :label="t('ai.optimizer.snapshotKind')">
                {{ detail.snapshot_summary.kind ?? '-' }}
              </el-descriptions-item>
              <el-descriptions-item :label="t('ai.optimizer.snapshotHasBaseline')">
                {{ detail.snapshot_summary.has_metric_baseline ? t('common.yes') : t('common.no') }}
              </el-descriptions-item>
              <el-descriptions-item :label="t('ai.optimizer.snapshotKeys')" :span="2">
                {{ (detail.snapshot_summary.keys || []).join(', ') || '-' }}
              </el-descriptions-item>
            </el-descriptions>
            <pre class="code-block">{{ prettySnapshot }}</pre>
          </template>

          <h4 class="section-title">{{ t('ai.optimizer.effectsTitle') }}</h4>
          <el-table v-loading="effectsLoading" :data="effects" size="small">
            <el-table-column prop="metric_name" :label="t('ai.optimizer.metric')" min-width="180" />
            <el-table-column :label="t('ai.optimizer.beforeApply')" width="120">
              <template #default="{ row }">{{ row.before_value }}</template>
            </el-table-column>
            <el-table-column :label="t('ai.optimizer.afterApply')" width="120">
              <template #default="{ row }">{{ row.after_value }}</template>
            </el-table-column>
            <el-table-column prop="measured_at" :label="t('ai.optimizer.measuredAt')" min-width="170" />
          </el-table>
          <div v-if="!effectsLoading && effects.length === 0" class="form-hint">
            {{ t('ai.optimizer.noEffects') }}
          </div>

          <div class="actions">
            <el-button
              type="success"
              :loading="actionLoading"
              :disabled="detail.status !== 'pending'"
              @click="onApply"
            >
              {{ t('ai.optimizer.apply') }}
            </el-button>
            <el-button
              type="danger"
              :loading="actionLoading"
              :disabled="detail.status !== 'pending'"
              @click="onReject"
            >
              {{ t('common.reject') }}
            </el-button>
            <el-button
              type="warning"
              :loading="actionLoading"
              :disabled="detail.status !== 'applied'"
              @click="onRollback"
            >
              {{ t('ai.optimizer.rollback') }}
            </el-button>
          </div>
        </template>
      </div>
    </el-drawer>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox } from 'element-plus'
import {
  analyzeNow,
  applyOptimization,
  getOptimization,
  listEffects,
  listOptimizations,
  rejectOptimization,
  rollbackOptimization,
  type OptimizationDetail,
  type OptimizationEffect,
  type OptimizationListItem,
  type OptimizationStatus,
  type OptimizationType,
} from '@/api/optimizer'
import { getSystemSettings } from '@/api/settings'
import { showError } from '@/utils/error'
import { optimizerText } from '@/utils/optimizerText'

const { t } = useI18n()

const settingsLoading = ref(true)
const aiEnabled = ref(false)

const items = ref<OptimizationListItem[]>([])
const total = ref(0)
const page = ref(1)
const pageSize = ref(20)
const loading = ref(false)
const filterType = ref<OptimizationType | ''>('')
const filterStatus = ref<OptimizationStatus | ''>('')
const filterConfidence = ref<number | undefined>(undefined)

const analyzing = ref(false)

const drawerVisible = ref(false)
const detail = ref<OptimizationDetail | null>(null)
const detailLoading = ref(false)
const effects = ref<OptimizationEffect[]>([])
const effectsLoading = ref(false)
const actionLoading = ref(false)

const prettySnapshot = computed(() =>
  detail.value ? JSON.stringify(detail.value.snapshot ?? {}, null, 2) : ''
)

function typeText(type: OptimizationType): string {
  const map: Record<OptimizationType, string> = {
    alert_threshold: t('ai.optimizer.typeAlertThreshold'),
    heal_rule: t('ai.optimizer.typeHealRule'),
    check_frequency: t('ai.optimizer.typeCheckFrequency'),
    retention_policy: t('ai.optimizer.typeRetentionPolicy'),
  }
  return map[type] || type
}

function statusText(s: OptimizationStatus): string {
  const map: Record<OptimizationStatus, string> = {
    pending: t('ai.statusPending'),
    applied: t('ai.statusApplied'),
    rejected: t('common.rejected'),
    rolled_back: t('ai.statusRolledBack'),
  }
  return map[s] || s
}

function statusTagType(
  s: OptimizationStatus
): 'info' | 'success' | 'warning' | 'danger' {
  if (s === 'applied') return 'success'
  if (s === 'rejected') return 'danger'
  if (s === 'rolled_back') return 'info'
  return 'warning'
}

async function loadSettings() {
  settingsLoading.value = true
  try {
    const data = await getSystemSettings()
    aiEnabled.value = data.ai_self_optimization_enabled === true
  } catch {
    aiEnabled.value = false
  } finally {
    settingsLoading.value = false
  }
}

async function loadList() {
  loading.value = true
  try {
    const data = await listOptimizations({
      type: filterType.value || undefined,
      status: filterStatus.value || undefined,
      confidence_min: filterConfidence.value,
      page: page.value,
      page_size: pageSize.value,
    })
    items.value = data.items
    total.value = data.total
  } catch (error) {
    showError(error, t('ai.optimizer.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onFilterChange() {
  page.value = 1
  loadList()
}

function onSizeChange() {
  page.value = 1
  loadList()
}

async function onAnalyze() {
  analyzing.value = true
  try {
    const result = await analyzeNow()
    if (result.created === 0) {
      ElMessage.info(t('ai.optimizer.analyzeDoneNoNew', { n: result.total_drafts }))
    } else {
      ElMessage.success(t('ai.optimizer.analyzeDoneNew', { n: result.created }))
    }
    page.value = 1
    await loadList()
  } catch (error) {
    showError(error, t('ai.optimizer.analyzeFailed'))
  } finally {
    analyzing.value = false
  }
}

async function openDetail(id: number) {
  drawerVisible.value = true
  detailLoading.value = true
  effects.value = []
  try {
    detail.value = await getOptimization(id)
    await loadEffects(id)
  } catch (error) {
    showError(error, t('ai.optimizer.loadDetailFailed'))
  } finally {
    detailLoading.value = false
  }
}

async function loadEffects(id: number) {
  effectsLoading.value = true
  try {
    effects.value = await listEffects(id)
  } catch (error) {
    showError(error, t('ai.optimizer.loadEffectsFailed'))
  } finally {
    effectsLoading.value = false
  }
}

async function onApply() {
  if (!detail.value) return
  try {
    await ElMessageBox.confirm(
      t('ai.optimizer.applyConfirmMsg'),
      t('ai.optimizer.applyConfirmTitle'),
      { type: 'warning' }
    )
  } catch {
    return
  }
  actionLoading.value = true
  try {
    detail.value = await applyOptimization(detail.value.id)
    ElMessage.success(t('ai.optimizer.applied'))
    await loadList()
    await loadEffects(detail.value.id)
  } catch (error) {
    showError(error, t('ai.optimizer.applyFailed'))
  } finally {
    actionLoading.value = false
  }
}

async function onReject() {
  if (!detail.value) return
  try {
    await ElMessageBox.confirm(t('ai.optimizer.rejectConfirmMsg'), t('ai.optimizer.rejectConfirmTitle'), {
      type: 'warning',
    })
  } catch {
    return
  }
  actionLoading.value = true
  try {
    detail.value = await rejectOptimization(detail.value.id)
    ElMessage.success(t('common.rejected'))
    await loadList()
  } catch (error) {
    showError(error, t('common.rejectFailed'))
  } finally {
    actionLoading.value = false
  }
}

async function onRollback() {
  if (!detail.value) return
  try {
    await ElMessageBox.confirm(
      t('ai.optimizer.rollbackConfirmMsg'),
      t('ai.optimizer.rollbackConfirmTitle'),
      { type: 'warning' }
    )
  } catch {
    return
  }
  actionLoading.value = true
  try {
    detail.value = await rollbackOptimization(detail.value.id)
    ElMessage.success(t('ai.optimizer.rolledBack'))
    await loadList()
  } catch (error) {
    showError(error, t('ai.optimizer.rollbackFailed'))
  } finally {
    actionLoading.value = false
  }
}

onMounted(async () => {
  await loadSettings()
  await loadList()
})
</script>

<style scoped>
.page-ai-optimizer {
  padding: 20px;
}

.page-title {
  margin: 0 0 20px;
  font-size: 20px;
}

.gate-alert,
.analyze-card,
.list-card {
  margin-bottom: 20px;
}

.form-hint {
  color: var(--el-text-color-secondary);
  font-size: 12px;
  margin-left: 12px;
}

.list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.filters {
  display: flex;
  gap: 8px;
  align-items: center;
}

.pagination {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}

.section-title {
  margin: 20px 0 10px;
  font-size: 15px;
}

.code-block {
  background: var(--el-fill-color-light);
  border: 1px solid var(--el-border-color-light);
  border-radius: 4px;
  padding: 12px;
  overflow: auto;
  max-height: 280px;
  white-space: pre-wrap;
  word-break: break-all;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  margin: 10px 0 0;
}

.actions {
  margin-top: 24px;
  display: flex;
  gap: 10px;
}
</style>
