/**
 * 优化建议文案翻译。
 *
 * 新数据：后端 current_value/suggested_value/reason/expected_effect 存
 * i18n 信封（`i18n:{"key":"optimizer.*","params":{...}}`），前端解码后
 * t(key, params) 渲染。
 * 历史数据：旧行为中文原文（无前缀），原样显示（不崩）。
 * LLM 润色后的 reason 是自然语言文本，同样原样显示。
 */
import i18n from '@/locales'

const I18N_PREFIX = 'i18n:'

export function optimizerText(value?: string | null): string {
  if (!value) {
    return ''
  }
  if (!value.startsWith(I18N_PREFIX)) {
    return value
  }
  try {
    const payload = JSON.parse(value.slice(I18N_PREFIX.length))
    const key = payload?.key
    if (typeof key === 'string' && i18n.global.te(key)) {
      return i18n.global.t(key, payload.params ?? {})
    }
  } catch {
    // 解析失败：按原样显示，不崩
  }
  return value
}
